"""Self-contained local teaching workspace; no external assets or persistence."""
from __future__ import annotations

import json

from .inheritance import InheritanceError, build_view, validate_bundle


def render_inheritance(bundle: dict, view: dict) -> str:
    """Render validated content and reject stale or altered derived views."""
    validation = validate_bundle(bundle)
    if validation["gate"] == "BLOCK":
        raise InheritanceError("INHERITANCE_RENDER_INVALID")
    expected = build_view(bundle)
    if view != expected:
        raise InheritanceError("INHERITANCE_RENDER_STALE_VIEW")
    payload = json.dumps({"bundle": bundle, "view": expected}, ensure_ascii=True,
                         allow_nan=False, sort_keys=True, separators=(",", ":"))
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return HTML.replace("__CSS__", CSS).replace("__JS__", JS).replace("__PAYLOAD__", payload)


